module wrapper(
    input logic clk,
    input logic rst,

    // Input.
    input  logic [7:0]  in_prot,
    input  logic [31:0] in_sIP,
    input  logic [31:0] in_dIP,
    input  logic [15:0] in_sPort,
    input  logic [15:0] in_dPort,
    input  logic [15:0] in_len,
    input  logic [9:0]  in_pktID,
    input  logic [4:0]  in_flits,
    input  logic [8:0]  in_tcp_flags,
    input  logic [2:0]  in_pkt_flags,
    input  logic [31:0] in_pkt_queue_id,
    input  logic [31:0] in_hash,
    input  logic [44:0] in_padding,
    input  logic        in_meta_valid,
    output logic        in_meta_ready,

    // Output.
    output logic [7:0]  out_prot,
    output logic [31:0] out_sIP,
    output logic [31:0] out_dIP,
    output logic [15:0] out_sPort,
    output logic [15:0] out_dPort,
    output logic [15:0] out_len,
    output logic [9:0]  out_pktID,
    output logic [4:0]  out_flits,
    output logic [8:0]  out_tcp_flags,
    output logic [2:0]  out_pkt_flags,
    output logic [31:0] out_pkt_queue_id,
    output logic [31:0] out_hash,
    output logic [44:0] out_padding,
    output logic        out_meta_valid,
    input  logic        out_meta_ready,

    input logic [31:0] nb_fallback_queues,
    input logic enable_rr
);

// Interface signals
metadata_t   in_meta_data;
metadata_t   out_meta_data;

always_comb begin
    in_meta_data.prot          = in_prot;
    in_meta_data.tuple.sIP     = in_sIP;
    in_meta_data.tuple.dIP     = in_dIP;
    in_meta_data.tuple.sPort   = in_sPort;
    in_meta_data.tuple.dPort   = in_dPort;
    in_meta_data.len           = in_len;
    in_meta_data.pktID         = in_pktID;
    in_meta_data.flits         = in_flits;
    in_meta_data.tcp_flags     = in_tcp_flags;
    in_meta_data.pkt_flags     = in_pkt_flags;
    in_meta_data.pkt_queue_id  = in_pkt_queue_id;
    in_meta_data.hash          = in_hash;
    in_meta_data.padding       = in_padding;

    out_prot         = out_meta_data.prot;
    out_sIP          = out_meta_data.tuple.sIP;
    out_dIP          = out_meta_data.tuple.dIP;
    out_sPort        = out_meta_data.tuple.sPort;
    out_dPort        = out_meta_data.tuple.dPort;
    out_len          = out_meta_data.len;
    out_pktID        = out_meta_data.pktID;
    out_flits        = out_meta_data.flits;
    out_tcp_flags    = out_meta_data.tcp_flags;
    out_pkt_flags    = out_meta_data.pkt_flags;
    out_pkt_queue_id = out_meta_data.pkt_queue_id;
    out_hash         = out_meta_data.hash;
    out_padding      = out_meta_data.padding;
end

flow_director uu_flow_director(
    .clk               (clk               ),
    .rst               (rst               ),
    .in_meta_data      (in_meta_data      ),
    .in_meta_valid     (in_meta_valid     ),
    .in_meta_ready     (in_meta_ready     ),
    .out_meta_data     (out_meta_data     ),
    .out_meta_valid    (out_meta_valid    ),
    .out_meta_ready    (out_meta_ready    ),
    .nb_fallback_queues(nb_fallback_queues),
    .enable_rr         (enable_rr         )
);

endmodule : wrapper

harness.src/router_fsm_tb.sv:
module router_fsm_tb;
  // Clock and reset
  reg        clock;
  reg        resetn;

  // Inputs to DUT
  reg        pkt_valid;
  reg  [1:0] data_in;
  reg        fifo_full;
  reg        fifo_empty_0;
  reg        fifo_empty_1;
  reg        fifo_empty_2;
  reg        soft_reset_0;
  reg        soft_reset_1;
  reg        soft_reset_2;
  reg        parity_done;
  reg        low_packet_valid;

  // Outputs from DUT
  wire       write_enb_reg;
  wire       detect_add;
  wire       ld_state;
  wire       laf_state;
  wire       lfd_state;
  wire       full_state;
  wire       rst_int_reg;
  wire       busy;

  // State values for internal reference
  localparam DECODE_ADDRESS   = 3'b000;
  localparam LOAD_FIRST_DATA  = 3'b001;
  localparam WAIT_TILL_EMPTY  = 3'b010;

  // Instantiate the FSM
  router_fsm uut (
    .clock(clock),
    .resetn(resetn),
    .pkt_valid(pkt_valid),
    .data_in(data_in),
    .fifo_full(fifo_full),
    .fifo_empty_0(fifo_empty_0),
    .fifo_empty_1(fifo_empty_1),
    .fifo_empty_2(fifo_empty_2),
    .soft_reset_0(soft_reset_0),
    .soft_reset_1(soft_reset_1),
    .soft_reset_2(soft_reset_2),
    .parity_done(parity_done),
    .low_packet_valid(low_packet_valid),
    .write_enb_reg(write_enb_reg),
    .detect_add(detect_add),
    .ld_state(ld_state),
    .laf_state(laf_state),
    .lfd_state(lfd_state),
    .full_state(full_state),
    .rst_int_reg(rst_int_reg),
    .busy(busy)
  );

  // Clock generation
  initial begin
    clock = 0;
    forever #5 clock = ~clock;
  end

  // Simple assertion task
  task assert_signal(input bit cond, input string name);
    begin
      if (!cond) begin
        $error("[ERROR] %s failed at time %0t", name, $time);
        $fatal(1);
      end
      else
        $display("[PASS] %s at time %0t", name, $time);
    end
  endtask

  // Test sequence
  initial begin
    // Initialize inputs
    resetn           = 0;
    pkt_valid        = 0;
    data_in          = 2'd0;
    fifo_full        = 0;
    fifo_empty_0     = 1;
    fifo_empty_1     = 1;
    fifo_empty_2     = 1;
    soft_reset_0     = 0;
    soft_reset_1     = 0;
    soft_reset_2     = 0;
    parity_done      = 0;
    low_packet_valid = 0;

    // Apply reset
    #20;
    resetn = 1;
    #10;

    // After reset, should be in DECODE_ADDRESS
    assert_signal(detect_add,      "detect_add after reset");
    assert_signal(!busy,           "busy after reset");

    // --------- Test 1: Normal packet to FIFO0 ---------
    $display("-- Test 1: Normal packet to FIFO0 --");
    data_in       = 2'd0;
    fifo_empty_0  = 1;
    pkt_valid     = 1;
    #10;
    assert_signal(lfd_state,       "LF first data");
    #10;
    assert_signal(ld_state,        "LD state begin");

    #30;
    pkt_valid = 0;
    low_packet_valid = 1;
    #10;
    assert_signal(write_enb_reg,  "write_enb in LOAD_PARITY");
    #10;
    assert_signal(rst_int_reg,    "rst_int_reg in CHECK_PARITY_ERROR");
    #10;

    // --------- Test 2: FIFO full during data load ---------
    $display("-- Test 2: FIFO full mid-packet --");
    soft_reset_0 = 1;
    #10;
    soft_reset_0 = 0;
    #10;
    data_in       = 2'd1;
    fifo_empty_1  = 1;
    pkt_valid     = 1;
    #10;
    assert_signal(lfd_state,      "LF first data (FIFO1)");
    #10;
    assert_signal(ld_state,       "LD state begin (FIFO1)");

    #10;
    fifo_full = 1;
    #10;
    assert_signal(full_state,     "full_state asserted");
    assert_signal(busy,           "busy during FIFO_FULL_STATE");

    fifo_full = 0;
    #10;
    parity_done      = 0;
    assert_signal(laf_state,      "laf_state asserted");
    low_packet_valid = 0;
    #10;
    assert_signal(ld_state,       "back to LD state after full");

    pkt_valid        = 0;
    low_packet_valid = 1;
    #10;
    assert_signal(write_enb_reg,  "write_enb in parity after full");
    #10;
    assert_signal(rst_int_reg,    "rst_int_reg in parity check after full");

    // --------- Test 3: DECODE_ADDRESS -> WAIT_TILL_EMPTY ---------
    $display("-- Test 3: Entry to WAIT_TILL_EMPTY state --");
    // Ensure FSM idle
    soft_reset_2 = 1; #10; soft_reset_2 = 0; #10;
    // Target FIFO2 is not empty, packet arrives
    data_in       = 2'd2;
    fifo_empty_2  = 0;
    pkt_valid     = 1;
    #10;
    // Check internal state is WAIT_TILL_EMPTY
    assert_signal(uut.present_state == WAIT_TILL_EMPTY,
                  "FSM entered WAIT_TILL_EMPTY");

    $display("All tests completed");
    $finish;
  end


  initial begin
      $dumpfile("router_fsm_tb.vcd");
      $dumpvars(0, router_fsm_tb);
  end
endmodule

